import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, TurnUsage } from 'claude-code'

import type { Pricing, RateLimit, Totals, WindowTokens } from '../types'

const limitsAtom = atom({ plugin: 'usage-band', key: 'limits' } as const, [] as RateLimit[])
const totalsAtom = atom({ plugin: 'usage-band', key: 'totals' } as const, null as Totals | null)
const sessionAtom = atom({ plugin: 'usage-band', key: 'session' } as const, null as WindowTokens | null)
const lastTurnAtom = atom({ plugin: 'usage-band', key: 'lastTurn' } as const, null as WindowTokens | null)

const HOUR = 3600_000
const WINDOWS = { fiveHour: { kind: 'five_hour', ms: 5 * HOUR }, week: { kind: 'seven_day', ms: 168 * HOUR } }

/** Per-minute buckets from scan.py: minute -> [input, output, cacheWrite, cacheRead, cost]. */
let buckets: Record<string, number[]> = {}
/** Per-session totals from scan.py: session id -> [tokens, cacheRead, cost]. */
let sessions: Record<string, number[]> = {}
let pricing: Pricing | null = null

export const sumSince = (from: number, b: Record<string, number[]>): WindowTokens => {
  const fromMinute = Math.floor(from / 60_000)
  let tokens = 0
  let cacheRead = 0
  let cost = 0
  for (const [minute, [i = 0, o = 0, cw = 0, cr = 0, usd = 0]] of Object.entries(b)) {
    if (Number(minute) < fromMinute) continue
    tokens += i + o + cw
    cacheRead += cr
    cost += usd
  }
  return { tokens, cacheRead, cost }
}

/**
 * USD for a turn's summed usage. A turn's usage has no cache-write split, so
 * writes are priced at the 1-hour rate Claude Code uses; 0 for an unknown model.
 */
export const turnCost = (p: Pricing, u: TurnUsage) => {
  const base = Object.keys(p.models)
    .sort((a, b) => b.length - a.length)
    .find(m => u.model.startsWith(m))
  const rates = base === undefined ? undefined : p.models[base]
  if (!rates) return 0
  const [input, output, read] = rates
  return (
    (u.input_tokens * input +
      u.output_tokens * output +
      u.cache_creation_input_tokens * input * p.cacheWrite1h +
      u.cache_read_input_tokens * read) /
    1e6
  )
}

export const fmtCost = (usd: number) =>
  usd >= 100 ? `$${usd.toFixed(0)}` : usd >= 0.01 || usd === 0 ? `$${usd.toFixed(2)}` : '<$0.01'

/** Where a window began: its reset time minus its length, else a rolling window. */
const windowStart = (limits: RateLimit[], kind: string, ms: number, now: number) => {
  const resetsAt = limits.find(l => l.kind === kind)?.resetsAt
  const reset = resetsAt ? Date.parse(resetsAt) : NaN
  return Number.isFinite(reset) && reset > now ? reset - ms : now - ms
}

export const fmtTokens = (n: number) =>
  n >= 1e9 ? `${(n / 1e9).toFixed(2)}B` : n >= 1e6 ? `${(n / 1e6).toFixed(1)}M` : n >= 1e3 ? `${(n / 1e3).toFixed(1)}K` : `${n}`

const pad = (n: number) => String(n).padStart(2, '0')
const fmtReset = (iso: string | undefined, withDate: boolean) => {
  if (!iso) return ''
  const d = new Date(iso)
  if (Number.isNaN(d.getTime())) return ''
  const hm = `${pad(d.getHours())}:${pad(d.getMinutes())}`
  return withDate ? `${d.getMonth() + 1}/${d.getDate()} ${hm}` : hm
}

async function recompute($: EngineInterface) {
  const limits = await read($, limitsAtom)
  const now = await $.clock.now()
  const totals: Totals = {
    fiveHour: sumSince(windowStart(limits, WINDOWS.fiveHour.kind, WINDOWS.fiveHour.ms, now), buckets),
    week: sumSince(windowStart(limits, WINDOWS.week.kind, WINDOWS.week.ms, now), buckets),
  }
  await update($, totalsAtom, () => totals)

  const [tokens = 0, cacheRead = 0, cost = 0] = sessions[await $.session.id()] ?? []
  await update($, sessionAtom, () => ({ tokens, cacheRead, cost }))
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const started = await next(e)
    pricing = await $.fs
      .read(`${$.plugin.root}/hooks/pricing.json`)
      .then(text => JSON.parse(text) as Pricing)
      .catch(() => null)
    const usage = await $.session.usage().catch(() => undefined)
    if (usage) await update($, limitsAtom, () => usage.rateLimits)

    // A scanner for the session's life: one JSON line of buckets a minute.
    void (async () => {
      const scan = $.process.spawn({ argv: ['python3', `${$.plugin.root}/hooks/scan.py`, '60'] })
      let pending = ''
      for await (const chunk of scan) {
        if (!('stream' in chunk) || chunk.stream !== 'stdout') continue
        pending += chunk.text
        let nl
        while ((nl = pending.indexOf('\n')) >= 0) {
          const line = pending.slice(0, nl)
          pending = pending.slice(nl + 1)
          try {
            const parsed = JSON.parse(line)
            buckets = parsed.b ?? {}
            sessions = parsed.s ?? {}
            await recompute($)
          } catch {}
        }
      }
    })()

    return started
  })

  on('session.measure', async ($, e, next) => {
    if (e.changed.includes('rateLimits')) {
      await update($, limitsAtom, () => e.rateLimits)
      await recompute($)
    }
    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    const u = result.usage
    if (u && e.agentId === undefined) {
      const turn = {
        tokens: u.input_tokens + u.output_tokens + u.cache_creation_input_tokens,
        cacheRead: u.cache_read_input_tokens,
        cost: pricing ? turnCost(pricing, u) : 0,
      }
      await update($, lastTurnAtom, () => turn)
    }
    return result
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e)
    const totals = await read($, totalsAtom)
    const limits = await read($, limitsAtom)
    const session = await read($, sessionAtom)
    const lastTurn = await read($, lastTurnAtom)
    if (!totals && limits.length === 0) return next(e)

    const { Box, Text } = $.ui.resolve(e)
    const part = (label: string, w: WindowTokens | undefined, kind: string, withDate: boolean) => {
      const limit = limits.find(l => l.kind === kind)
      const pct = limit ? limit.percentUsed : undefined
      const color = pct === undefined ? undefined : pct >= 90 ? 'red' : pct >= 70 ? 'yellow' : 'green'
      const reset = fmtReset(limit?.resetsAt, withDate)
      return (
        <Text>
          <Text bold>{label} </Text>
          <Text>{w ? `${fmtTokens(w.tokens)} tok` : '…'}</Text>
          {w ? <Text color="cyan"> {fmtCost(w.cost)}</Text> : null}
          {w && w.cacheRead > 0 ? <Text dimColor> (+{fmtTokens(w.cacheRead)} cache read)</Text> : null}
          {pct !== undefined ? <Text color={color}> {pct}%</Text> : null}
          {reset ? <Text dimColor> ↻{reset}</Text> : null}
        </Text>
      )
    }

    const tok = (label: string, w: WindowTokens) => (
      <Text>
        <Text bold>{label} </Text>
        <Text>{fmtTokens(w.tokens)} tok</Text>
        <Text color="cyan"> {fmtCost(w.cost)}</Text>
        {w.cacheRead > 0 ? <Text dimColor> (+{fmtTokens(w.cacheRead)} cache read)</Text> : null}
      </Text>
    )

    return (
      <Box flexDirection="column">
        <Text>
          {part('5h', totals?.fiveHour, 'five_hour', false)}
          <Text dimColor>  │  </Text>
          {part('Week', totals?.week, 'seven_day', true)}
        </Text>
        {session || lastTurn ? (
          <Text>
            {session ? tok('Session', session) : null}
            {session && lastTurn ? <Text dimColor>  │  </Text> : null}
            {lastTurn ? tok('Last turn', lastTurn) : null}
          </Text>
        ) : null}
      </Box>
    )
  })
}

