/** One rate-limit window as `$.session.usage()` reports it. */
export type RateLimit = { kind: string; percentUsed: number; resetsAt?: string }

/**
 * Token totals of one window: input + output + cache writes, cache reads apart,
 * and what all four cost in USD at API rates.
 */
export type WindowTokens = { tokens: number; cacheRead: number; cost: number }

/** hooks/pricing.json: USD per million tokens, [input, output, cache read]. */
export type Pricing = {
  cacheWrite5m: number
  cacheWrite1h: number
  fast: Record<string, number>
  models: Record<string, [number, number, number]>
}

export type Totals = { fiveHour: WindowTokens; week: WindowTokens }

declare module 'claude-code' {
  interface PluginState {
    'usage-band': {
      limits: RateLimit[]
      totals: Totals | null
      /** This conversation's tokens, its subagents included. */
      session: WindowTokens | null
      /** The last main-loop turn's tokens. */
      lastTurn: WindowTokens | null
    }
  }
}
